class Employee {
    protected String name;
    protected double salary;
    public Employee(String name, double salary) {
        this.name = name;
        this.salary = salary;
    }
    public void work() {
        System.out.println(name + " is working.");
    }
}

interface BonusEligible {
    double calculateBonus(double ratingFactor);
}

// Extends MUST precede implements!
class SeniorEngineer extends Employee implements BonusEligible {
    public SeniorEngineer(String name, double salary) {
        super(name, salary);
    }

    @Override
    public double calculateBonus(double ratingFactor) {
        return salary * 0.15 * ratingFactor;
    }
}

public class EmployeeApp {
    public static void main(String[] args) {
        SeniorEngineer eng = new SeniorEngineer("Jordan", 120000.0);
        eng.work(); // From Employee
        double bonus = eng.calculateBonus(1.2); // From BonusEligible
        System.out.println("Bonus: $" + String.format("%.2f", bonus));
    }
}

